/**
 * @suppress
 */
public object FfiConverterTypeHttpTransport: FfiConverter<HttpTransport, Pointer> {
    internal val handleMap = UniffiHandleMap<HttpTransport>()

    override fun lower(value: HttpTransport): Pointer {
        return Pointer(handleMap.insert(value))
    }

    override fun lift(value: Pointer): HttpTransport {
        return HttpTransportImpl(value)
    }

    override fun read(buf: ByteBuffer): HttpTransport {
        // The Rust code always writes pointers as 8 bytes, and will
        // fail to compile if they don't fit.
        return lift(Pointer(buf.getLong()))
    }

    override fun allocationSize(value: HttpTransport) = 8UL

    override fun write(value: HttpTransport, buf: ByteBuffer) {
        // The Rust code always expects pointers written as 8 bytes,
        // and will fail to compile if they don't fit.
        buf.putLong(Pointer.nativeValue(lower(value)))
    }
}


