    }
    )
    }
    

    

    
    companion object {
        
    /**
     * Открывает мессенджер поверх зашифрованного хранилища.
     *
     * `database_key` — 32 байта, полученные растягиванием PIN через
     * Argon2id. Ключ приходит готовым: растягивание живёт в
