/**
 * Ошибка, пересекающая границу FFI.
 *
 * Варианты намеренно грубые. Различие между «неверный тег аутентификации»
 * и «неверная длина» — это оракул для атакующего, а сообщение об ошибке
 * попадает в системный лог платформы, который читается кем угодно.
 */
sealed class FfiException(message: String): kotlin.Exception(message) {
        
    /**
     * Ошибка ядра GasApp.
     */
        class Core(message: String) : FfiException(message)
        
    /**
     * 🔐 Сервер называет для собеседника не тот ключ, что известен.
     *
     * Отдельным вариантом, а не текстом внутри [`FfiError::Core`]:
     * интерфейс показывает это как предупреждение о возможной
     * подмене и ведёт к выбору ключа, а не как сбой отправки.
     * Разбирать для этого строку ошибки значило бы завязать
     * безопасность на формулировку.
     */
        class IdentityChanged(message: String) : FfiException(message)
        
    /**
     * 🔐 Ключ собеседника не подтверждён вне сервера.
     *
     * Своим вариантом, как и [`FfiError::IdentityChanged`]: интерфейс
     * ведёт к сверке safety number, а не показывает сбой.
     */
        class PeerUnconfirmed(message: String) : FfiException(message)
        
    /**
     * Входные данные не прошли валидацию на границе.
     */
        class InvalidArgument(message: String) : FfiException(message)
        
    /**
     * Имя занято другим аккаунтом.
     *
     * Своим вариантом: интерфейс ведёт обратно к полю имени, а не
     * показывает сбой сети (см. [`GasAppError::UsernameTaken`]).
     */
        class UsernameTaken(message: String) : FfiException(message)
        
    /**
     * Строка не похожа на адрес почты.
     */
        class InvalidEmail(message: String) : FfiException(message)
        
    /**
     * Код из письма не принят: неверный, истёкший или сгоревший.
     *
     * Своим вариантом: интерфейс ведёт обратно к полю кода.
     */
        class EmailCodeRejected(message: String) : FfiException(message)
        
    /**
     * На этот адрес почты уже зарегистрирован аккаунт.
     */
        class EmailTaken(message: String) : FfiException(message)
        
    /**
     * Действие доступно только с премиумом (создание канала) либо
     * только владельцу (запись в канал).
     */
        class PremiumRequired(message: String) : FfiException(message)
        
    /**
     * В ядре произошла паника.
     *
     * Сообщение паники сознательно **не** передаётся: оно может содержать
     * значения переменных, а значит потенциально — чувствительные данные.
     */
        class Panic(message: String) : FfiException(message)
        

    companion object ErrorHandler : UniffiRustCallStatusErrorHandler<FfiException> {
        override fun lift(error_buf: RustBuffer.ByValue): FfiException = FfiConverterTypeFfiError.lift(error_buf)
    }
}

/**
 * @suppress
 */
public object FfiConverterTypeFfiError : FfiConverterRustBuffer<FfiException> {
    override fun read(buf: ByteBuffer): FfiException {
        
            return when(buf.getInt()) {
            1 -> FfiException.Core(FfiConverterString.read(buf))
            2 -> FfiException.IdentityChanged(FfiConverterString.read(buf))
            3 -> FfiException.PeerUnconfirmed(FfiConverterString.read(buf))
            4 -> FfiException.InvalidArgument(FfiConverterString.read(buf))
            5 -> FfiException.UsernameTaken(FfiConverterString.read(buf))
            6 -> FfiException.InvalidEmail(FfiConverterString.read(buf))
            7 -> FfiException.EmailCodeRejected(FfiConverterString.read(buf))
            8 -> FfiException.EmailTaken(FfiConverterString.read(buf))
            9 -> FfiException.PremiumRequired(FfiConverterString.read(buf))
            10 -> FfiException.Panic(FfiConverterString.read(buf))
            else -> throw RuntimeException("invalid error enum value, something is very wrong!!")
        }
        
    }

    override fun allocationSize(value: FfiException): ULong {
        return 4UL
    }

    override fun write(value: FfiException, buf: ByteBuffer) {
        when(value) {
            is FfiException.Core -> {
                buf.putInt(1)
                Unit
            }
            is FfiException.IdentityChanged -> {
                buf.putInt(2)
                Unit
            }
            is FfiException.PeerUnconfirmed -> {
                buf.putInt(3)
                Unit
            }
            is FfiException.InvalidArgument -> {
                buf.putInt(4)
                Unit
            }
            is FfiException.UsernameTaken -> {
                buf.putInt(5)
                Unit
            }
            is FfiException.InvalidEmail -> {
                buf.putInt(6)
                Unit
            }
            is FfiException.EmailCodeRejected -> {
                buf.putInt(7)
                Unit
            }
            is FfiException.EmailTaken -> {
                buf.putInt(8)
                Unit
            }
            is FfiException.PremiumRequired -> {
                buf.putInt(9)
                Unit
            }
            is FfiException.Panic -> {
                buf.putInt(10)
                Unit
            }
        }.let { /* this makes the `when` an expression, which ensures it is exhaustive */ }
    }

}



/**
 * Режим выхода в сеть.
 */
sealed class FfiProxy {
    
    /**
     * Напрямую: сервер видит IP-адрес.
     */
    object Direct : FfiProxy()
    
    
    /**
     * Через SOCKS5-прокси.
     */
    data class Socks5(
        /**
         * Имя хоста или IP-адрес прокси.
         */
        val `host`: kotlin.String, 
        /**
         * Порт прокси.
         */
        val `port`: kotlin.UShort) : FfiProxy() {
        companion object
    }
    
    /**
     * Через Tor, встроенный в приложение.
     */
    object Tor : FfiProxy()
    
    

    
    companion object
}

/**
 * @suppress
 */
public object FfiConverterTypeFfiProxy : FfiConverterRustBuffer<FfiProxy>{
    override fun read(buf: ByteBuffer): FfiProxy {
        return when(buf.getInt()) {
            1 -> FfiProxy.Direct
            2 -> FfiProxy.Socks5(
                FfiConverterString.read(buf),
                FfiConverterUShort.read(buf),
                )
            3 -> FfiProxy.Tor
            else -> throw RuntimeException("invalid enum value, something is very wrong!!")
        }
    }

    override fun allocationSize(value: FfiProxy) = when(value) {
        is FfiProxy.Direct -> {
            // Add the size for the Int that specifies the variant plus the size needed for all fields
            (
                4UL
            )
        }
        is FfiProxy.Socks5 -> {
            // Add the size for the Int that specifies the variant plus the size needed for all fields
            (
                4UL
                + FfiConverterString.allocationSize(value.`host`)
                + FfiConverterUShort.allocationSize(value.`port`)
            )
        }
        is FfiProxy.Tor -> {
            // Add the size for the Int that specifies the variant plus the size needed for all fields
            (
                4UL
            )
        }
    }

    override fun write(value: FfiProxy, buf: ByteBuffer) {
        when(value) {
            is FfiProxy.Direct -> {
                buf.putInt(1)
                Unit
            }
            is FfiProxy.Socks5 -> {
                buf.putInt(2)
                FfiConverterString.write(value.`host`, buf)
                FfiConverterUShort.write(value.`port`, buf)
                Unit
            }
            is FfiProxy.Tor -> {
                buf.putInt(3)
                Unit
            }
        }.let { /* this makes the `when` an expression, which ensures it is exhaustive */ }
    }
}







/**
 * Сбой транспорта платформы.
 *
 * Свой тип, а не [`FfiError`]: тот объявлен «плоским» (`flat_error`),
 * а плоские ошибки UniFFI умеет только отдавать наружу, но не принимать
 * обратно — ошибка, брошенная платформой из [`HttpTransport::execute`],
 * поднимала панику внутри ядра («Can't lift flat errors»). Любой сбой
 * сети — таймаут Tor, обрыв — превращался в «внутреннюю ошибку»
 * посреди операции вместо [`GasAppError::Network`], которого ждут
 * повторы и очередь отправки.
 */
sealed class FfiTransportException: kotlin.Exception() {
    
    /**
     * Сеть недоступна: соединение не открылось или оборвалось.
     */
    class Network(
        ) : FfiTransportException() {
        override val message
            get() = ""
    }
    

    companion object ErrorHandler : UniffiRustCallStatusErrorHandler<FfiTransportException> {
        override fun lift(error_buf: RustBuffer.ByValue): FfiTransportException = FfiConverterTypeFfiTransportError.lift(error_buf)
    }

    
}

/**
 * @suppress
 */
public object FfiConverterTypeFfiTransportError : FfiConverterRustBuffer<FfiTransportException> {
    override fun read(buf: ByteBuffer): FfiTransportException {
        

        return when(buf.getInt()) {
            1 -> FfiTransportException.Network()
            else -> throw RuntimeException("invalid error enum value, something is very wrong!!")
        }
    }

    override fun allocationSize(value: FfiTransportException): ULong {
        return when(value) {
            is FfiTransportException.Network -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
            )
        }
    }

    override fun write(value: FfiTransportException, buf: ByteBuffer) {
        when(value) {
            is FfiTransportException.Network -> {
                buf.putInt(1)
                Unit
            }
        }.let { /* this makes the `when` an expression, which ensures it is exhaustive */ }
    }

}



